def count_mean_stretches(pnl, target):
    pre = [0]
    for x in pnl:
        pre.append(pre[-1] + x)
    total = 0
    for i in range(len(pnl)):
        for j in range(i + 1, len(pnl) + 1):
            if (pre[j] - pre[i]) / (j - i) == target:
                total += 1
    return total

def count_mean_stretches(pnl, target):
    seen = {0: 1}
    run = 0
    total = 0
    for x in pnl:
        run += x
        total += seen.get(run - target, 0)
        seen[run] = seen.get(run, 0) + 1
    return total
